def _backfill_existing_applications():
    """Freeze normalization here so future service changes cannot alter old migrations."""
    import re
    import unicodedata
    from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit
    from uuid import uuid4

    def norm(value):
        return " ".join(re.sub(r"[^\w\s+#]", " ", unicodedata.normalize("NFKC", value).casefold()).split())

    def company_norm(value):
        words = norm(value).split()
        while len(words) > 1 and words[-1] in {
            "inc",
            "incorporated",
            "llc",
            "ltd",
            "limited",
            "pvt",
            "private",
            "corp",
            "corporation",
        }:
            words.pop()
        return " ".join(words)

    def url_key(value):
        if not value:
            return None
        p = urlsplit(value.strip())
        query = [
            (k, v)
            for k, v in parse_qsl(p.query, keep_blank_values=True)
            if not k.casefold().startswith("utm_") and k.casefold() not in {"gclid", "fbclid"}
        ]
        host = (p.hostname or "").casefold()
        if p.port and p.port not in (80, 443):
            host += f":{p.port}"
        return urlunsplit(("https", host, p.path.rstrip("/") or "/", urlencode(sorted(query)), ""))

    connection = op.get_bind()
    companies = {}
    for row in connection.execute(sa.text("SELECT * FROM applications")).mappings():
        # Preserve distinct original names instead of silently merging similarly named companies.
        name = row["company_name"]
        if name not in companies:
            companies[name] = uuid4()
            connection.execute(
                sa.text("INSERT INTO companies (id, name, normalized_name) VALUES (:id,:name,:normalized)"),
                {"id": companies[name], "name": name, "normalized": company_norm(name)},
            )
        connection.execute(
            sa.text("""UPDATE applications SET company_id=:company_id,
            normalized_company_name=:company, normalized_role_title=:role,
            job_url_key=:job, source_url_key=:source, contact_email_key=:email WHERE id=:id"""),
            {
                "company_id": companies[name],
                "company": company_norm(name),
                "role": norm(row["role_title"]),
                "job": url_key(row["job_url"]),
                "source": url_key(row["source_url"]),
                "email": row["contact_email"].casefold() if row["contact_email"] else None,
                "id": row["id"],
            },
        )
